import React, { useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import './styles.css';
import {
  createUniverse, hydrateUniverse, RARITY, SERIES_META, countryFlag, countryIso2, getDriver, getTeam, getStaff,
  getEngine, getSponsor, getMainBrand, SCHEMA_VERSION, currentDriverRating, effectiveDriverSkill,
} from './data.js';
import {
  SESSION_TEMPLATES, simulateWeeks, simulateToSeasonEnd,
  advanceToNextSeason, driverStandings, constructorStandings, powerRankings,
  goatLeaderboard, circuitFitRanking, sponsorFit,
} from './sim.js';
import { saveSlot, loadSlot, deleteSlot, listSlots, exportUniverse, importUniverse } from './storage.js';

const SERIES_ORDER=['F1','F2','F3','F4','FE','WEC'];
const RARITY_ORDER={Generational:6,Legend:5,Epic:4,Rare:3,Uncommon:2,Common:1};
const NAV=[
  ['home','Home'],['competitions','Competitions'],['schedule','Schedule'],['results','Results'],
  ['drivers','Drivers'],['teams','Teams'],['paddock','Paddock'],['almanac','Almanac'],['more','More'],
];
const clamp=(value,min,max)=>Math.max(min,Math.min(max,value));
const avg=(values)=>values.length?values.reduce((sum,value)=>sum+value,0)/values.length:0;
const money=(value)=>`$${Math.round(value||0)}m`;
const careerMultiplier=(driver)=>driver?.careerCurve?.[driver.curveIndex]||driver?.careerMultiplier||.9;
const currentRating=(driver)=>currentDriverRating(driver);
const seriesName=(series)=>SERIES_META[series]?.name||series;

function Flag({driver=null,country='',code=''}){
  const source=code||driver?.countryCode||country||driver?.country||'';const iso2=countryIso2(source);const label=code||driver?.countryCode||iso2;
  return <span className="flag" title={country||driver?.country||label}><b aria-hidden="true" style={{display:'none'}}>{countryFlag(source)}</b><img src={`${import.meta.env.BASE_URL}flags/${iso2.toLowerCase()}.png`} alt={`${country||driver?.country||label} flag`} onError={(event)=>{event.currentTarget.style.display='none';if(event.currentTarget.previousElementSibling)event.currentTarget.previousElementSibling.style.display='inline';}}/><small>{label}</small></span>;
}
function SeatBadge({driver=null,seat=null,team=null}){const raw=seat??driver?.seat??0;const value=(driver?.role==='Test driver'||driver?.role==='Reserve driver')?3:raw;if(!value)return null;const primary=team?.primary||team?.color||'#555';const secondary=team?.secondary||team?.color||'#888';return <span className="seat-badge" style={{'--seat-team':primary,'--seat-team-2':secondary}} title={value===1?'First driver':value===2?'Second driver':value===3?'Test / reserve driver':`Driver ${value}`}><i>{value}</i></span>}
function RarityTag({rarity}){return <span className={`rarity rarity-${String(rarity).toLowerCase()}`} style={{'--rarity':RARITY[rarity]?.color}}>{rarity}</span>}
function SeriesTag({series,role=null}){return <span className="series-tag" style={{'--series':SERIES_META[series]?.color||'#777'}}>{role==='Test driver'?'TEST':role==='Free agent'?'FREE':role==='Retired'?'RET':series}</span>}
function TeamStripe({team}){const primary=team?.primary||team?.color||'#444';const secondary=team?.secondary||team?.color||'#888';return <span className="team-stripe" style={{background:`linear-gradient(${primary},${secondary})`}}/>}
function Pill({children,active,onClick}){return <button className={`pill ${active?'active':''}`} onClick={onClick}>{children}</button>}
function Panel({title,eyebrow,children,action=null,className=''}){return <section className={`panel ${className}`}><header><div>{eyebrow&&<small>{eyebrow}</small>}<h2>{title}</h2></div>{action}</header>{children}</section>}
function PageTitle({eyebrow,title,subtitle,action=null}){return <div className="page-title"><div><small>{eyebrow}</small><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>}
function Empty({title,body}){return <div className="empty"><b>F1</b><h3>{title}</h3><p>{body}</p></div>}
function Progress({label,value}){return <div className="progress"><span>{label}</span><i><b style={{width:`${clamp(value,0,100)}%`}}/></i><strong>{Math.round(value)}</strong></div>}

function UniverseHub({slots,setSlots,onLoad,onCreate,onImport}){
  const [name,setName]=useState('My F1 Universe');
  const [busy,setBusy]=useState(false);
  const inputRef=useRef(null);
  const create=async(slot)=>{setBusy(true);try{await onCreate(slot,name.trim()||`Universe ${slot}`);}finally{setBusy(false);}};
  const remove=async(slot)=>{if(!window.confirm(`Delete Universe Slot ${slot}? This cannot be undone.`))return;await deleteSlot(slot);setSlots(await listSlots());};
  const importFile=async(event)=>{const file=event.target.files?.[0];if(!file)return;setBusy(true);try{await onImport(file);}finally{setBusy(false);event.target.value='';}};
  return <div className="launcher">
    <div className="launcher-grid-bg"/>
    <header className="launcher-head"><div className="f1-logo">F1</div><div><small>WORLD CHRONICLE</small><h1>Choose a universe</h1></div></header>
    <div className="launcher-intro"><p>Every slot is a separate procedural motorsport history: F4 prospects, feeder champions, F1 dynasties, team takeovers, sponsors, weather, records and GOAT debates.</p><label>New universe name<input value={name} onChange={(event)=>setName(event.target.value)} maxLength={38}/></label></div>
    <div className="slot-grid">{[1,2,3].map((slot)=>{const meta=slots.find((item)=>item.slot===slot);return <article className={`slot-card ${meta?'occupied':'empty-slot'}`} key={slot}>
      <div className="slot-number">SLOT {slot}</div>
      {meta?<><h2>{meta.label}</h2><div className="slot-season"><b>{meta.year}</b><span>{meta.phase}<br/>Round {Math.min((meta.round||0)+1,24)}</span></div><small>Last played {new Date(meta.updatedAt).toLocaleString()} · schema v{meta.schemaVersion||'legacy'}</small>{(meta.schemaVersion||0)<5&&<p className="legacy-warning">This slot belongs to an early prototype and cannot be migrated safely. Export it from the old build or delete it before creating a new universe.</p>}<div className="slot-actions"><button className="primary" onClick={()=>onLoad(slot)} disabled={busy||(meta.schemaVersion||0)<5}>Load universe</button><button className="danger" onClick={()=>remove(slot)} disabled={busy}>Delete</button></div></>:<><div className="empty-mark">+</div><h2>Empty universe</h2><p>Generate procedural drivers, staff, sponsors and the complete racing world.</p><button className="primary" onClick={()=>create(slot)} disabled={busy}>Create in Slot {slot}</button></>}
    </article>})}</div>
    <div className="launcher-footer"><button className="outline" onClick={()=>inputRef.current?.click()}>Import universe JSON</button><span>IndexedDB saves · no browser localStorage quota</span></div>
    <input ref={inputRef} hidden type="file" accept="application/json" onChange={importFile}/>
  </div>;
}

function App(){
  const [slots,setSlots]=useState([]);
  const [universe,setUniverse]=useState(null);
  const [currentSlot,setCurrentSlot]=useState(null);
  const [page,setPageState]=useState('home');
  const [selectedDriver,setSelectedDriverState]=useState(null);
  const [selectedTeam,setSelectedTeamState]=useState(null);
  const [selectedEvent,setSelectedEventState]=useState(null);
  const [selectedStaff,setSelectedStaffState]=useState(null);
  const [selectedCompetition,setSelectedCompetition]=useState('F1');
  const [toast,setToast]=useState('');
  const [busy,setBusy]=useState(false);
  const autosaveReady=useRef(false);

  const applyRoute=(route={page:'home'})=>{setPageState(route.page||'home');setSelectedDriverState(route.driver||null);setSelectedTeamState(route.team||null);setSelectedEventState(route.event||null);setSelectedStaffState(route.staff||null);};
  const navigate=(route,replace=false)=>{const hash=route.driver?`#/driver/${route.driver}`:route.team?`#/team/${route.team}`:route.staff?`#/staff/${route.staff}`:route.event?`#/event/${route.event.series}/${route.event.eventId}`:`#/${route.page||'home'}`;window.history[replace?'replaceState':'pushState'](route,'',hash);applyRoute(route);};
  const setPage=(id)=>navigate({page:id});
  const setSelectedDriver=(id)=>id&&navigate({driver:id});
  const setSelectedTeam=(id)=>id&&navigate({team:id});
  const setSelectedStaff=(id)=>id&&navigate({staff:id});
  const setSelectedEvent=(event)=>event&&navigate({event});
  const back=()=>window.history.length>1?window.history.back():navigate({page:'home'},true);

  useEffect(()=>{listSlots().then(setSlots).catch(()=>setSlots([]));const pop=(event)=>applyRoute(event.state||{page:'home'});window.addEventListener('popstate',pop);return()=>window.removeEventListener('popstate',pop);},[]);
  useEffect(()=>{if(!universe||!currentSlot||!universe.settings?.autoSave)return;if(!autosaveReady.current){autosaveReady.current=true;return;}const timer=window.setTimeout(()=>saveSlot(currentSlot,universe,universe.name||`Universe ${currentSlot}`).then(()=>listSlots().then(setSlots)).catch(()=>{}),800);return()=>window.clearTimeout(timer);},[universe,currentSlot]);

  const notify=(message)=>{setToast(message);window.setTimeout(()=>setToast(''),2600);};
  const load=async(slot)=>{const data=await loadSlot(slot);if(!data)return;if((data.schemaVersion||0)<5){window.alert('This save uses an early schema that cannot be migrated safely.');return;}setUniverse(hydrateUniverse(data));setCurrentSlot(slot);navigate({page:'home'},true);autosaveReady.current=false;};
  const create=async(slot,name)=>{const data=createUniverse((Date.now()+slot*101)%2147483000);data.name=name;await saveSlot(slot,data,name);setSlots(await listSlots());setUniverse(hydrateUniverse(data));setCurrentSlot(slot);navigate({page:'home'},true);autosaveReady.current=false;};
  const importSave=async(file)=>{const data=await importUniverse(file);if((data.schemaVersion||0)<5){window.alert('This save uses an early schema that cannot be migrated safely.');return;}const empty=[1,2,3].find((slot)=>!slots.some((item)=>item.slot===slot));if(!empty){notify('Delete a slot before importing.');return;}data.name=data.name||'Imported universe';await saveSlot(empty,data,data.name);setSlots(await listSlots());setUniverse(hydrateUniverse(data));setCurrentSlot(empty);navigate({page:'home'},true);};
  const saveNow=async()=>{if(!universe||!currentSlot)return;await saveSlot(currentSlot,universe,universe.name||`Universe ${currentSlot}`);setSlots(await listSlots());notify(`Saved to Slot ${currentSlot}`);};
  const saveAndExit=async()=>{await saveNow();setUniverse(null);setCurrentSlot(null);applyRoute({page:'home'});autosaveReady.current=false;};
  const perform=(fn,message)=>{setBusy(true);window.setTimeout(()=>{setUniverse((previous)=>fn(previous));setBusy(false);if(message)notify(message);},35);};

  if(!universe)return <UniverseHub slots={slots} setSlots={setSlots} onLoad={load} onCreate={create} onImport={importSave}/>;

  const worldEvents=SERIES_ORDER.flatMap((series)=>competitionCalendar(universe,series).map((event)=>({...event,series}))).filter((event)=>event.status!=='Complete').sort((a,b)=>(a.week||99)-(b.week||99)||a.round-b.round);
  const event=worldEvents[0];
  const week=()=>perform((u)=>simulateWeeks(u,1),'One motorsport week simulated');
  const month=()=>perform((u)=>simulateWeeks(u,4),'Four motorsport weeks simulated');
  const season=()=>window.confirm('Simulate every remaining event in every championship?')&&perform(simulateToSeasonEnd,'All championships completed');
  const nextYear=()=>perform(advanceToNextSeason,`Welcome to ${universe.year+1}`);
  const leaders=Object.fromEntries(SERIES_ORDER.map((series)=>[series,driverStandings(universe,series)[0]]));
  const pageProps={universe,setUniverse,setPage,setSelectedDriver,setSelectedTeam,setSelectedEvent,setSelectedStaff,selectedCompetition,setSelectedCompetition,week,month,season,nextYear,busy,saveNow,saveAndExit,currentSlot};
  const normalContent={home:<Home {...pageProps}/>,competitions:<Competitions {...pageProps}/>,schedule:<Schedule {...pageProps}/>,results:<Results {...pageProps}/>,drivers:<Drivers {...pageProps}/>,teams:<Teams {...pageProps}/>,paddock:<Paddock {...pageProps}/>,almanac:<Almanac {...pageProps}/>,more:<More {...pageProps}/>}[page];
  const content=selectedDriver?<DriverPage universe={universe} driver={getDriver(universe,selectedDriver)} back={back} openTeam={setSelectedTeam} openStaff={setSelectedStaff}/>:selectedTeam?<TeamPage universe={universe} team={getTeam(universe,selectedTeam)} back={back} openDriver={setSelectedDriver} openStaff={setSelectedStaff}/>:selectedStaff?<StaffPage universe={universe} member={getStaff(universe,selectedStaff)} back={back} openTeam={setSelectedTeam} openDriver={setSelectedDriver}/>:selectedEvent?<EventPage universe={universe} selection={selectedEvent} back={back} openDriver={setSelectedDriver} openTeam={setSelectedTeam}/>:normalContent;

  return <div className="app-shell">
    <header className="topbar"><button className="brand" onClick={()=>setPage('home')}><b>F1</b><span>WORLD CHRONICLE</span></button><nav>{NAV.map(([id,label])=><button key={id} className={!selectedDriver&&!selectedTeam&&!selectedEvent&&!selectedStaff&&page===id?'active':''} onClick={()=>setPage(id)}>{label}</button>)}</nav><div className="top-actions"><button onClick={saveNow}>Save</button><button onClick={saveAndExit}>Slots</button></div></header>
    <div className="ticker"><div><small>WEEK {universe.currentWeek||1} · {event?.series||'WORLD'}</small><b>{event?.country||'Season complete'}</b><span>{event?.name||'Run the off-season'}</span></div><div className="ticker-series">{['F1','F2','F4'].map((series)=><span key={series}><small>{series}</small><b>{leaders[series]?.name||'—'}</b></span>)}</div><div className="ticker-controls">{universe.phase==='Season complete'?<button className="primary small" onClick={nextYear} disabled={busy}>Begin {universe.year+1}</button>:<><button onClick={week} disabled={busy}>+1 week</button><button className="primary small" onClick={month} disabled={busy}>+4 weeks</button></>}</div></div>
    <main>{content}</main>{toast&&<div className="toast">{toast}</div>}
  </div>;
}

function Home({universe,setPage,setSelectedDriver,setSelectedTeam,setSelectedEvent,week,month,season,busy}){
  const allEvents=SERIES_ORDER.flatMap((series)=>competitionCalendar(universe,series).map((event)=>({...event,series}))).sort((a,b)=>(a.week||99)-(b.week||99)||a.round-b.round);
  const upcoming=allEvents.filter((event)=>event.status!=='Complete').slice(0,8);
  const leaders=SERIES_ORDER.map((series)=>({series,driver:driverStandings(universe,series)[0]}));
  const prospects=universe.drivers.filter((driver)=>driver.active&&['F2','F3','F4'].includes(driver.series)&&['Generational','Legend'].includes(driver.rarity)).sort((a,b)=>RARITY_ORDER[b.rarity]-RARITY_ORDER[a.rarity]||currentRating(b)-currentRating(a)).slice(0,6);
  const headline=upcoming[0];
  return <section className="page"><div className="hero world-hero"><div className="hero-copy"><small>{universe.name.toUpperCase()} · {universe.year} · WEEK {universe.currentWeek||1}</small><h1>Motorsport<br/><em>World</em></h1><p>{headline?`${headline.series} travels next to ${headline.country} for ${headline.name}.`:'Every championship is complete.'} The universe advances by time, so F4, F3, F2, Formula E, WEC and F1 events all happen on their own calendars.</p><div className="actions"><button className="primary" onClick={week} disabled={busy}>Simulate 1 week</button><button className="outline" onClick={month} disabled={busy}>Simulate 4 weeks</button><button className="outline" onClick={season} disabled={busy}>To year end</button></div></div><div className="hero-card world-next"><small>NEXT WORLD EVENT</small><SeriesTag series={headline?.series||'F1'}/><Flag country={headline?.country}/><h2>{headline?.name||'Off-season'}</h2><p>Week {headline?.week||'—'} · Round {headline?.round||'—'}</p><button className="link" onClick={()=>headline&&setSelectedEvent({series:headline.series,eventId:headline.id,circuitId:headline.circuitId||headline.id})}>Open event page ›</button></div></div>
  <div className="dashboard"><Panel title="World calendar" eyebrow="NEXT EIGHT EVENTS" className="span-2" action={<button className="link" onClick={()=>setPage('schedule')}>Full schedule</button>}><div className="world-calendar-strip">{upcoming.map((event)=><button key={`${event.series}-${event.id}`} onClick={()=>setSelectedEvent({series:event.series,eventId:event.id,circuitId:event.circuitId||event.id})}><SeriesTag series={event.series}/><b>W{event.week}</b><Flag country={event.country}/><span>{event.name}<small>{event.city}</small></span></button>)}</div></Panel>
  <Panel title="Championship leaders" eyebrow="ALL COMPETITIONS"><div className="leader-list compact">{leaders.map(({series,driver})=><button key={series} onClick={()=>driver&&setSelectedDriver(driver.id)}><SeriesTag series={series}/><Flag driver={driver}/><span><b>{driver?.name||'—'}</b><small>{driver?.season.points||0} points</small></span></button>)}</div></Panel>
  <Panel title="Elite prospects" eyebrow="F4 · F3 · F2" className="span-2" action={<button className="link" onClick={()=>setPage('drivers')}>All drivers</button>}><div className="prospect-grid">{prospects.map((driver)=><button key={driver.id} onClick={()=>setSelectedDriver(driver.id)}><div><SeriesTag series={driver.series}/><RarityTag rarity={driver.rarity}/></div><Flag driver={driver}/><h3>{driver.name}</h3><p>{driver.age} years · {getTeam(universe,driver.teamId)?.name}</p><span><b>{currentRating(driver)}</b>current ability</span></button>)}</div></Panel>
  <Panel title="Teams to watch" eyebrow="FINANCES + CAR"><div className="leader-list compact">{universe.teams.slice().sort((a,b)=>(b.finances.projectedBalance||0)-(a.finances.projectedBalance||0)).slice(0,5).map((team)=><button key={team.id} onClick={()=>setSelectedTeam(team.id)}><TeamStripe team={team}/><span><b>{team.name}</b><small>{money(team.finances.projectedBalance)} balance · car {Math.round(team.baseline)}</small></span></button>)}</div></Panel></div></section>;
}

function Competitions({universe,selectedCompetition,setSelectedCompetition,setSelectedDriver,setSelectedTeam}){
  const [tab,setTab]=useState('Overview');
  const series=selectedCompetition;
  const standings=driverStandings(universe,series);
  const teams=teamStandings(universe,series);
  const history=[...universe.seasonArchive].reverse().map((season)=>({year:season.year,...(season.series?.[series]||{})})).filter((item)=>item.championId);
  const stats=[...universe.drivers].map((driver)=>{
    const seasons=(driver.career.seasons||[]).filter((item)=>item.series===series);
    const titles=(driver.trophies||[]).filter((trophy)=>trophy.includes(`${series} Champion`)||(series==='F1'&&trophy.includes('Formula 1 World Champion'))).length;
    return {...driver,seriesStarts:seasons.length,seriesPoints:seasons.reduce((sum,item)=>sum+(item.points||0),0)+(driver.series===series?driver.season.points:0),seriesWins:seasons.reduce((sum,item)=>sum+(item.wins||0),0)+(driver.series===series?driver.season.wins:0),seriesTitles:titles};
  }).filter((driver)=>driver.seriesStarts||driver.series===series).sort((a,b)=>b.seriesTitles-a.seriesTitles||b.seriesWins-a.seriesWins||b.seriesPoints-a.seriesPoints);
  const leader=standings[0];
  return <section className="page"><PageTitle eyebrow="MOTORSPORT WORLD" title="Competitions" subtitle="Each championship is a permanent navigable competition, not background flavor. Track a prospect from F4 through the ladder—or a veteran rebuilding a career in Formula E or WEC."/>
    <div className="competition-picker">{SERIES_ORDER.map((item)=><button key={item} className={series===item?'active':''} style={{'--series':SERIES_META[item].color}} onClick={()=>{setSelectedCompetition(item);setTab('Overview')}}><b>{item}</b><span>{SERIES_META[item].name}</span><small>{driverStandings(universe,item).length} drivers</small></button>)}</div>
    <div className="tab-row">{['Overview','Current Year','History','Stats'].map((item)=><Pill key={item} active={tab===item} onClick={()=>setTab(item)}>{item}</Pill>)}</div>
    {tab==='Overview'&&<div className="two-col"><Panel title={`${seriesName(series)} leader`} eyebrow={`${universe.year} OVERVIEW`}>{leader?<div className="champion-card"><div><SeriesTag series={series}/><RarityTag rarity={leader.rarity}/></div><Flag driver={leader}/><h2>{leader.name}</h2><p>{getTeam(universe,leader.teamId)?.name} · {leader.age} years · {leader.style}</p><strong>{leader.season.points} points</strong><button className="outline" onClick={()=>setSelectedDriver(leader.id)}>Driver profile</button></div>:<Empty title="No active field" body="This competition currently has no active drivers."/>}</Panel><Panel title="Championship snapshot" eyebrow="TOP THREE"><div className="podium-list">{standings.slice(0,3).map((driver,index)=><button key={driver.id} onClick={()=>setSelectedDriver(driver.id)}><strong>P{index+1}</strong><Flag driver={driver}/><span><b>{driver.name}</b><small>{getTeam(universe,driver.teamId)?.name}</small></span><em>{driver.season.points}</em></button>)}</div><div className="competition-facts"><span><b>{teams[0]?.name||'—'}</b>Leading team</span><span><b>{standings.filter((driver)=>['Generational','Legend'].includes(driver.rarity)).length}</b>Elite talents</span><span><b>{Math.min(...standings.map((driver)=>driver.age))}</b>Youngest</span></div></Panel></div>}
    {tab==='Current Year'&&<div className="competition-current"><Panel title="Driver standings" eyebrow={`${universe.year} ${series}`}><StandingsTable universe={universe} rows={standings} openDriver={setSelectedDriver}/></Panel><Panel title="Team standings" eyebrow="CONSTRUCTORS / ENTRANTS"><div className="team-table">{teams.map((team,index)=><button key={team.id} onClick={()=>setSelectedTeam(team.id)}><strong>{index+1}</strong>{series==='F1'?<TeamStripe team={team}/>:<i style={{background:team.color}}/>}<span><b>{team.name}</b><small>{team.wins||team.seasonWins||0} wins</small></span><em>{team.points??team.seasonPoints??0}</em></button>)}</div></Panel><Panel title="Season leaders" eyebrow="STATS"><div className="stat-leaders">{[
      ['Wins',[...standings].sort((a,b)=>b.season.wins-a.season.wins)[0],d=>d.season.wins],['Podiums',[...standings].sort((a,b)=>b.season.podiums-a.season.podiums)[0],d=>d.season.podiums],['Current value',[...standings].sort((a,b)=>currentRating(b)-currentRating(a))[0],currentRating],['Youngest', [...standings].sort((a,b)=>a.age-b.age)[0],d=>`${d.age}y`]
    ].map(([label,driver,value])=><button key={label} onClick={()=>driver&&setSelectedDriver(driver.id)}><small>{label}</small><b>{driver?.name||'—'}</b><em>{driver?value(driver):'—'}</em></button>)}</div></Panel></div>}
    {tab==='History'&&(history.length?<div className="history-grid">{history.map((season)=><Panel key={season.year} title={`${season.year} ${series}`} eyebrow="CHAMPIONS"><div className="history-champions"><span><small>DRIVER</small><b>{season.championName}</b></span><span><small>TEAM</small><b>{season.teamChampionName}</b></span></div><div className="mini-standings">{season.standings?.slice(0,3).map((driver,index)=><div key={driver.id}><strong>{index+1}</strong><span>{driver.name}</span><em>{driver.points}</em></div>)}</div></Panel>)}</div>:<Empty title="The first season is still being written" body={`Complete ${universe.year} to create the permanent ${series} history.`}/>) }
    {tab==='Stats'&&<Panel title={`All-time ${series} drivers`} eyebrow="TITLES · WINS · POINTS"><div className="alltime-table">{stats.slice(0,50).map((driver,index)=><button key={driver.id} onClick={()=>setSelectedDriver(driver.id)}><strong>{index+1}</strong><Flag driver={driver}/><RarityTag rarity={driver.rarity}/><span><b>{driver.name}</b><small>{driver.seriesStarts} recorded seasons</small></span><em>{driver.seriesTitles} titles</em><em>{driver.seriesWins} wins</em><em>{driver.seriesPoints} pts</em></button>)}</div></Panel>}
  </section>;
}

function StandingsTable({universe,rows,openDriver}){return <div className="standings-table">{rows.map((driver,index)=>{const team=getTeam(universe,driver.teamId);return <button key={driver.id} onClick={()=>openDriver(driver.id)}><strong>{index+1}</strong><Flag driver={driver}/><RarityTag rarity={driver.rarity}/><SeatBadge driver={driver} team={team}/><TeamStripe team={team}/><span><b>{driver.name}</b><small>{team?.name||driver.role} · {driver.trackSpecialty}</small></span><em>{driver.season.wins} W</em><em>{driver.season.podiums} P</em><b>{driver.season.points}</b></button>})}</div>}

function teamStandings(universe,series){
  if(series==='F1')return constructorStandings(universe).map((team)=>({...team,points:team.seasonPoints,wins:team.seasonWins}));
  return (universe.feederTeams?.[series]||[]).map((team)=>({...team,points:team.points??team.season?.points??0,wins:team.wins??team.season?.wins??0})).sort((a,b)=>b.points-a.points||b.wins-a.wins||(b.baseline||b.rating||0)-(a.baseline||a.rating||0));
}
function competitionCalendar(universe,series){return universe.competitionCalendars?.[series]||(series==='F1'?universe.calendar:[])}
function competitionResults(universe,series){return universe.competitionEventResults?.[series]||[]}
function Schedule({universe,setSelectedEvent,week,month,season,busy}){
  const [series,setSeries]=useState('All');
  const events=(series==='All'?SERIES_ORDER.flatMap((item)=>competitionCalendar(universe,item).map((event)=>({...event,series:item}))):competitionCalendar(universe,series).map((event)=>({...event,series}))).sort((a,b)=>(a.week||99)-(b.week||99)||a.round-b.round);
  return <section className="page"><PageTitle eyebrow={`${universe.year} · WEEK ${universe.currentWeek||1}`} title="World schedule" subtitle="One shared motorsport calendar. Simulating time completes every F4, F3, F2, Formula E, WEC and F1 event scheduled inside that window." action={<div className="simulation-actions"><button onClick={week} disabled={busy}>+1 week</button><button onClick={month} disabled={busy}>+4 weeks</button><button className="danger" onClick={season} disabled={busy}>End of year</button></div>}/><div className="tab-row scroll"><Pill active={series==='All'} onClick={()=>setSeries('All')}>All</Pill>{SERIES_ORDER.map((item)=><Pill key={item} active={series===item} onClick={()=>setSeries(item)}>{item}</Pill>)}</div><div className="calendar-grid world-grid">{events.map((event)=><button key={`${event.series}-${event.id}`} className={`calendar-card ${event.status?.toLowerCase()} ${(event.week||99)===(universe.currentWeek||1)?'next':''}`} onClick={()=>setSelectedEvent({series:event.series,eventId:event.id,circuitId:event.circuitId||event.id})}><header><SeriesTag series={event.series}/><small>WEEK {event.week} · ROUND {event.round}</small><Flag country={event.country}/></header><h2>{event.country}</h2><p>{event.city} · {event.name}</p><div className="circuit-tags"><span>{event.rain}% rain · {event.temp}°C</span><span>{event.traits?.high>=88?'High-speed':event.traits?.low>=86?'Technical':event.traits?.straight>=90?'Power':event.traits?.street>=85?'Street':'Balanced'}</span><span>{event.status}</span></div></button>)}</div></section>;
}

function Results({universe,setSelectedDriver,setSelectedEvent}){
  const [series,setSeries]=useState('F1');const records=[...competitionResults(universe,series)].reverse();
  return <section className="page"><PageTitle eyebrow={`${universe.year} MOTORSPORT WORLD`} title="Results" subtitle="F1, the feeder ladder, Formula E and WEC all preserve complete event weekends. Open a result for Friday practice, Q1–Q3, race classification, circuit history and records."/><div className="competition-picker compact-picker">{SERIES_ORDER.map((item)=><button key={item} className={series===item?'active':''} style={{'--series':SERIES_META[item].color}} onClick={()=>setSeries(item)}><b>{item}</b><span>{SERIES_META[item].name}</span><small>{competitionResults(universe,item).length} results</small></button>)}</div>{records.length?<div className="result-grid">{records.map((record)=>{const winner=getDriver(universe,record.winnerId);const event=record.event||competitionCalendar(universe,series).find((item)=>item.id===record.eventId);return <Panel key={record.id} title={event?.name||`${event?.country} event`} eyebrow={`${series} · ROUND ${record.round}`} action={<button className="link" onClick={()=>setSelectedEvent({series,eventId:record.eventId,circuitId:record.circuitId})}>Open event ›</button>}><div className="result-summary"><span><small>WINNER</small><button onClick={()=>setSelectedDriver(winner?.id)}><Flag driver={winner}/><SeatBadge driver={winner} team={getTeam(universe,winner?.teamId)}/><b>{winner?.name}</b></button></span><span><small>POLE / WEATHER</small><b>{getDriver(universe,record.poleId)?.name||'—'}</b><em>{record.weather?.qualifying||'—'} {record.weather?.qualifyingTemperature!=null?`${record.weather.qualifyingTemperature}°C`:''} → {record.weather?.race||'—'} {record.weather?.raceTemperature!=null?`${record.weather.raceTemperature}°C`:''}</em></span></div><div className="mini-standings">{record.podium?.map((podium)=>{const driver=getDriver(universe,podium.driverId);const team=getTeam(universe,podium.teamId);return <button key={podium.driverId} onClick={()=>setSelectedDriver(driver?.id)}><strong>{podium.position}</strong><Flag driver={driver}/><SeatBadge driver={driver} team={team}/><span>{driver?.name}<small>{team?.name}</small></span></button>})}</div></Panel>})}</div>:<Empty title={`No ${series} results yet`} body="Simulate race weekends to begin this competition's event archive."/>}</section>
}

function Drivers({universe,setSelectedDriver}){
  const [scope,setScope]=useState('All');const [rarity,setRarity]=useState('All');const [query,setQuery]=useState('');const [sort,setSort]=useState('Current value');
  const drivers=useMemo(()=>universe.drivers.filter((driver)=>{
    const scopeMatch=scope==='All'||scope===driver.series||(scope==='Free Agents'&&driver.role==='Free agent')||(scope==='Test Drivers'&&driver.role==='Test driver')||(scope==='Retired'&&driver.role==='Retired');
    const rarityMatch=rarity==='All'||driver.rarity===rarity;const text=`${driver.name} ${driver.country} ${getTeam(universe,driver.teamId)?.name||''}`.toLowerCase();return scopeMatch&&rarityMatch&&text.includes(query.toLowerCase());
  }).sort((a,b)=>sort==='Points'?b.season.points-a.season.points:sort==='Age'?a.age-b.age:sort==='Rarity'?RARITY_ORDER[b.rarity]-RARITY_ORDER[a.rarity]||currentRating(b)-currentRating(a):currentRating(b)-currentRating(a)),[universe,scope,rarity,query,sort]);
  return <section className="page"><PageTitle eyebrow={`${universe.drivers.length} PEOPLE`} title="Drivers" subtitle="The driver database is the whole universe: F1, the complete ladder, Formula E, WEC, free agents, test drivers and retired careers."/><div className="driver-controls"><div className="tab-row scroll">{['All','F1','F2','F3','F4','FE','WEC','Free Agents','Test Drivers','Retired'].map((item)=><Pill key={item} active={scope===item} onClick={()=>setScope(item)}>{item}</Pill>)}</div><input placeholder="Search driver, country or team" value={query} onChange={(event)=>setQuery(event.target.value)}/><select value={rarity} onChange={(event)=>setRarity(event.target.value)}><option>All</option>{Object.keys(RARITY).map((item)=><option key={item}>{item}</option>)}</select><select value={sort} onChange={(event)=>setSort(event.target.value)}><option>Current value</option><option>Points</option><option>Age</option><option>Rarity</option></select></div><div className="driver-count">Showing {drivers.length} drivers</div><div className="driver-table">{drivers.map((driver)=><button key={driver.id} onClick={()=>setSelectedDriver(driver.id)}><SeriesTag series={driver.series} role={driver.role}/><Flag driver={driver}/><RarityTag rarity={driver.rarity}/><SeatBadge driver={driver} team={getTeam(universe,driver.teamId)}/><span className="driver-name"><b>{driver.name}</b><small>{driver.age} · {driver.trackSpecialty}</small></span><span><TeamStripe team={getTeam(universe,driver.teamId)}/><b>{getTeam(universe,driver.teamId)?.name||driver.role}</b><small>{driver.country}</small></span><em><b>{currentRating(driver)}</b>current</em><em><b>{driver.season.points}</b>points</em><em><b>{driver.happiness?.overall||'—'}</b>happy</em><strong>›</strong></button>)}</div></section>;
}

function LiveryCar({team,universe}){
  const brand=getMainBrand(universe,team.mainBrandId);const sponsors=(team.sponsorIds||[]).map((id)=>getSponsor(universe,id)).filter(Boolean);
  return <div className="livery-car" style={{'--primary':team.primary,'--secondary':team.secondary}}><svg viewBox="0 0 860 220" role="img" aria-label={`${team.name} car`}><path className="car-main" d="M22 148 L48 85 L126 78 L155 120 L345 102 L406 77 L510 80 L550 103 L734 118 L818 152 L815 177 L650 177 L615 151 L248 151 L210 181 L70 181 Z"/><path className="car-side" d="M148 126 L347 111 L408 88 L530 89 L575 120 L719 127 L676 151 L243 151 L208 174 L91 174 Z"/><path className="car-secondary" d="M265 132 L410 102 L546 103 L600 129 L520 143 L235 148 Z"/><circle cx="150" cy="165" r="42"/><circle cx="680" cy="165" r="42"/><circle className="hub" cx="150" cy="165" r="18"/><circle className="hub" cx="680" cy="165" r="18"/><text x="380" y="130">{brand?.name||team.short}</text><text className="sponsor-text" x="520" y="146">{sponsors[0]?.name||''}</text></svg></div>;
}

function Teams({universe,setSelectedTeam}){
  const [series,setSeries]=useState('All');const [sort,setSort]=useState('Points');
  const all=[...universe.teams.map((team)=>({...team,series:'F1',displayPoints:team.season?.points??team.seasonPoints??0,displayRevenue:team.finances?.totalIncome||0,displayCar:team.baseline||avg(Object.values(team.car||{}))})),...Object.entries(universe.feederTeams||{}).flatMap(([competition,teams])=>teams.map((team)=>({...team,series:competition,displayPoints:team.points||team.season?.points||0,displayRevenue:team.finances?.totalIncome||team.finances?.income||0,displayCar:team.baseline||team.rating||avg(Object.values(team.carProfile||{}))})))];
  const filtered=all.filter((team)=>series==='All'||team.series===series).sort((a,b)=>sort==='Revenue'?b.displayRevenue-a.displayRevenue:sort==='Car quality'?b.displayCar-a.displayCar:b.displayPoints-a.displayPoints||b.displayCar-a.displayCar);
  return <section className="page"><PageTitle eyebrow={`${all.length} ACTIVE ORGANIZATIONS`} title="Teams" subtitle="Every championship is part of the universe. Filter and compare teams by current points, revenue or car quality, then open a permanent team page."/><div className="team-controls"><div className="tab-row scroll"><Pill active={series==='All'} onClick={()=>setSeries('All')}>All</Pill>{SERIES_ORDER.map((item)=><Pill key={item} active={series===item} onClick={()=>setSeries(item)}>{item}</Pill>)}</div><select value={sort} onChange={(event)=>setSort(event.target.value)}><option>Points</option><option>Revenue</option><option>Car quality</option></select></div><div className="team-grid compact-teams">{filtered.map((team,index)=>{const brand=team.series==='F1'?getMainBrand(universe,team.mainBrandId):null;return <button key={team.id} onClick={()=>setSelectedTeam(team.id)} style={{'--team':team.primary||team.color||SERIES_META[team.series]?.color}}><header><SeriesTag series={team.series}/><strong>{index+1}</strong><span><b>{team.name}</b><small>{brand?`${brand.country} · ${brand.tier}`:team.country}</small></span></header><div className="compact-team-band"/><div className="team-card-stats"><span><b>{team.displayPoints}</b>points</span><span><b>{money(team.displayRevenue)}</b>revenue</span><span><b>{Math.round(team.displayCar)}</b>car</span><span><b>{money(team.finances?.projectedBalance||0)}</b>balance</span></div></button>})}</div></section>;
}

function Paddock({universe,setSelectedDriver,setSelectedTeam,setSelectedStaff}){
  const [view,setView]=useState('Magazine');const [category,setCategory]=useState('All');const categories=['All',...new Set(universe.stories.map((story)=>story.category))];const stories=universe.stories.filter((story)=>category==='All'||story.category===category);const openSubject=(story)=>{const ids=story.subjects||[];const driverId=ids.find((id)=>getDriver(universe,id));if(driverId){setSelectedDriver(driverId);return;}const staffId=ids.find((id)=>getStaff(universe,id));if(staffId){setSelectedStaff(staffId);return;}const teamId=ids.find((id)=>getTeam(universe,id));if(teamId)setSelectedTeam(teamId);};const market=[...(universe.marketHistory||[])].sort((a,b)=>b.year-a.year||String(b.id).localeCompare(a.id));
  return <section className="page"><PageTitle eyebrow="THE PADDOCK" title="World Chronicle magazine" subtitle="Narratives connect results to careers, weather, staff, sponsors, finances, promotions, takeovers and historic context."/><div className="tab-row"><Pill active={view==='Magazine'} onClick={()=>setView('Magazine')}>Magazine</Pill><Pill active={view==='Market'} onClick={()=>setView('Market')}>Driver Market ({market.length})</Pill></div>{view==='Magazine'?<><div className="tab-row scroll">{categories.map((item)=><Pill key={item} active={category===item} onClick={()=>setCategory(item)}>{item}</Pill>)}</div><div className="magazine-grid">{stories.map((story,index)=><article key={story.id} className={index===0?'lead':''} onClick={()=>openSubject(story)}><small>{story.category} · {story.year}{story.round?` · R${story.round}`:''}</small><h2>{story.headline}</h2><p>{story.dek}</p><footer><span>{story.thread?.replaceAll('-',' ')||'world chronicle'}</span><b>Open subject ›</b></footer></article>)}</div></>:<>{market.length?<div className="market-list">{market.map((move)=>{const driver=getDriver(universe,move.driverId);const fromTeam=getTeam(universe,move.from?.teamId);const toTeam=getTeam(universe,move.to?.teamId);return <button key={move.id} onClick={()=>setSelectedDriver(move.driverId)}><div className="market-driver"><Flag driver={driver}/><RarityTag rarity={driver?.rarity}/><span><b>{move.driverName}</b><small>{move.year} market · {move.reason}</small></span></div><div className="market-route"><span><SeriesTag series={move.from?.series} role={move.from?.role}/><SeatBadge seat={move.from?.seat} team={fromTeam}/><b>{move.from?.teamName}</b><small>{money(move.from?.salary)}</small></span><strong>→</strong><span><SeriesTag series={move.to?.series} role={move.to?.role}/><SeatBadge seat={move.to?.seat} team={toTeam}/><b>{move.to?.teamName}</b><small>{money(move.to?.salary)}</small></span></div></button>})}</div>:<Empty title="The first market has not opened" body="Complete the season and begin the next year. Every move will show championship, team, seat hierarchy and salary."/>}</>}</section>
}

function Almanac({universe,setSelectedDriver,setSelectedTeam}){const [tab,setTab]=useState('GOAT');const [mode,setMode]=useState('F1');const goats=goatLeaderboard(universe,mode).slice(0,50);return <section className="page"><PageTitle eyebrow="PERMANENT HISTORY" title="Almanac" subtitle="Titles, wins, points, lineages, seasons and careers remain navigable as the universe grows."/><div className="tab-row">{['GOAT','Seasons','Team Lineage','Records'].map((item)=><Pill key={item} active={tab===item} onClick={()=>setTab(item)}>{item}</Pill>)}</div>{tab==='GOAT'&&<><div className="tab-row compact">{['F1','All Motorsport','Peak','Longevity'].map((item)=><Pill key={item} active={mode===item} onClick={()=>setMode(item)}>{item}</Pill>)}</div><Panel title="Driver GOAT index" eyebrow={`${mode.toUpperCase()} FORMULA`}><div className="goat-table">{goats.map((driver,index)=><button key={driver.id} onClick={()=>setSelectedDriver(driver.id)}><strong>{index+1}</strong><Flag driver={driver}/><RarityTag rarity={driver.rarity}/><span><b>{driver.name}</b><small>{driver.career.titles} F1 titles · {driver.career.f1Wins} wins · {driver.career.seriesTitles} other titles</small></span><em>{driver.goat.toFixed(1)}</em></button>)}</div></Panel></>}{tab==='Seasons'&&(universe.seasonArchive.length?<div className="history-grid">{[...universe.seasonArchive].reverse().map((season)=><Panel key={season.year} title={`${season.year} season`} eyebrow={`${season.calendar.length} GRANDS PRIX`}><div className="history-champions"><span><small>F1 DRIVER</small><b>{season.championName}</b></span><span><small>F1 TEAM</small><b>{season.constructorName}</b></span></div><div className="series-champions">{SERIES_ORDER.slice(1).map((series)=><span key={series}><b>{series}</b>{season.series?.[series]?.championName||'—'}</span>)}</div></Panel>)}</div>:<Empty title="No archived seasons" body="Complete the current year to create the first permanent season record."/>)}{tab==='Team Lineage'&&<div className="lineage-grid">{universe.teams.map((team)=><button key={team.id} onClick={()=>setSelectedTeam(team.id)}><LiveryCar team={team} universe={universe}/><h3>{team.name}</h3>{team.lineage.map((entry)=><span key={`${entry.year}-${entry.name}`}><b>{entry.year}</b>{entry.name} · {entry.owner}</span>)}</button>)}</div>}{tab==='Records'&&<div className="record-grid"><Panel title="Universe totals" eyebrow="LIVE"><div className="record-list"><span><b>{universe.drivers.length}</b>Drivers created</span><span><b>{universe.drivers.filter((driver)=>driver.role==='Retired').length}</b>Retired careers</span><span><b>{universe.seasonArchive.length}</b>Completed seasons</span><span><b>{universe.teams.reduce((sum,team)=>sum+team.lineage.length-1,0)}</b>Team identity changes</span></div></Panel><Panel title="Career leaders" eyebrow="F1"><div className="record-list"><span><b>{Math.max(...universe.drivers.map((driver)=>driver.career.f1Wins))}</b>Most wins</span><span><b>{Math.max(...universe.drivers.map((driver)=>driver.career.titles))}</b>Most titles</span><span><b>{Math.max(...universe.drivers.map((driver)=>driver.career.f1Points))}</b>Most points</span><span><b>{Math.max(...universe.drivers.map((driver)=>driver.career.f1Starts))}</b>Most starts</span></div></Panel></div>}</section>}

function More({universe,setUniverse,week,month,season,nextYear,busy,saveNow,saveAndExit,currentSlot}){const update=(key,value)=>setUniverse((previous)=>({...previous,settings:{...previous.settings,[key]:value}}));return <section className="page"><PageTitle eyebrow={`UNIVERSE SLOT ${currentSlot} · SCHEMA V${SCHEMA_VERSION}`} title="Universe controls" subtitle="Save management, global simulation cadence and commissioner settings."/><div className="two-col"><Panel title="Save and simulation" eyebrow="UNIVERSE"><div className="button-stack"><button className="primary" onClick={saveNow}>Save now</button><button className="outline" onClick={()=>exportUniverse(universe)}>Export JSON</button><button className="outline" onClick={saveAndExit}>Save and return to slots</button>{universe.phase==='Season complete'?<button className="primary" onClick={nextYear} disabled={busy}>Run off-season and begin {universe.year+1}</button>:<><button onClick={week} disabled={busy}>Simulate 1 week</button><button onClick={month} disabled={busy}>Simulate 4 weeks</button><button className="danger" onClick={season} disabled={busy}>Simulate all competitions to year end</button></>}</div></Panel><Panel title="Commissioner settings" eyebrow="WORLD DYNAMISM"><Setting label="Calendar churn" value={universe.settings.calendarChurn} options={['Locked','Conservative','Aggressive']} onChange={(value)=>update('calendarChurn',value)}/><Setting label="Team dynamism" value={universe.settings.teamDynamism} options={['Static','Plausible']} onChange={(value)=>update('teamDynamism',value)}/><Setting label="Protected identities" value={universe.settings.authenticLock?'On':'Off'} options={['On','Off']} onChange={(value)=>update('authenticLock',value==='On')}/><Setting label="Autosave" value={universe.settings.autoSave?'On':'Off'} options={['On','Off']} onChange={(value)=>update('autoSave',value==='On')}/></Panel></div><Panel title="Systems active" eyebrow="BUILD COVERAGE"><div className="coverage">{['Page-based browser navigation and back history','All drivers and teams across six competitions','1-week, 4-week and full-year world simulation','1–10 facilities with annual decay and investment','Driver hierarchy based on quality, tenure, experience and success','Named race engineer assigned to Driver 1 and Driver 2','Rarity-colored transferable staff','Effective current skills separated from raw base talent','Weather, circuit DNA, finances, transfers, history and GOAT'].map((item)=><span key={item}>✓ {item}</span>)}</div></Panel></section>}

function Setting({label,value,options,onChange}){return <label className="setting"><span><b>{label}</b><small>Current: {value}</small></span><select value={value} onChange={(event)=>onChange(event.target.value)}>{options.map((option)=><option key={option}>{option}</option>)}</select></label>}

function lapDisplay(value){if(value==null)return'—';if(typeof value==='string')return value;const minutes=Math.floor(value/60);return `${minutes}:${(value%60).toFixed(3).padStart(6,'0')}`}
function countLeaders(records,key,limit=10){const counts=new Map();records.forEach((record)=>{const id=record[key];if(id)counts.set(id,(counts.get(id)||0)+1);});return [...counts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,limit)}
function circuitIdentity(event){const traits=event?.traits||{};const ranked=[['High-speed car',traits.high],['Technical / low-speed car',traits.low],['Power and low drag',traits.straight],['Tyre management',traits.tyre],['Street-circuit agility',traits.street]].sort((a,b)=>(b[1]||0)-(a[1]||0));const driver=ranked[0]?.[0]==='High-speed car'?'High-speed specialists':ranked[0]?.[0]==='Technical / low-speed car'?'Technical and precision drivers':ranked[0]?.[0]==='Power and low drag'?'Late brakers and power-circuit specialists':ranked[0]?.[0]==='Tyre management'?'Tyre whisperers':'Street-circuit specialists';return{car:ranked[0]?.[0]||'Balanced car',driver}}
function EventResultTable({universe,session,openDriver}){const rows=session?.rows||[];if(!rows.length)return <Empty title="No classification" body="This session has not been completed in the current season."/>;return <div className="event-table"><div className="event-table-head"><span>Pos</span><span>Driver</span><span>Team</span><span>Time / gap</span><span>Pts</span></div>{rows.map((row,index)=>{const driver=getDriver(universe,row.driverId);const team=getTeam(universe,row.teamId||driver?.teamId);return <button key={`${session.key}-${row.driverId}-${index}`} onClick={()=>openDriver(driver?.id)}><strong>{row.position||index+1}</strong><span className="event-driver"><Flag driver={driver}/><SeatBadge driver={driver} team={team}/><b>{driver?.name||'Unknown'}</b><RarityTag rarity={driver?.rarity}/></span><span><TeamStripe team={team}/>{team?.name||'—'}</span><em>{row.status&&row.status!=='Running'?row.gap||row.status:row.gap||lapDisplay(row.time)}</em><b>{row.points||0}</b></button>})}</div>}
function EventPage({universe,selection,back,openDriver,openTeam}){
  const [tab,setTab]=useState('Overview');const [sessionKey,setSessionKey]=useState('FP1');const series=selection.series||'F1';const calendar=competitionCalendar(universe,series);const event=calendar.find((item)=>item.id===selection.eventId)||calendar.find((item)=>(item.circuitId||item.id)===selection.circuitId);const circuitId=selection.circuitId||event?.circuitId||event?.id;
  const records=[...(universe.eventArchive||[]),...competitionResults(universe,series)].filter((record)=>record.series===series&&(record.circuitId===circuitId||record.eventId===selection.eventId)).sort((a,b)=>b.year-a.year);const latest=records[0];const current=records.find((record)=>record.year===universe.year);const identity=circuitIdentity(event||latest?.event);
  const winLeaders=countLeaders(records,'winnerId',10);const poleLeaders=countLeaders(records,'poleId',10);const teamLeaders=countLeaders(records,'teamWinnerId',10);const fastest=records.filter((record)=>record.fastestLapTime).sort((a,b)=>a.fastestLapTime-b.fastestLapTime).slice(0,3);const sessionKeys=['FP1','FP2','FP3','SQ1','SQ2','SQ3','S','Q1','Q2','Q3','R'].filter((key)=>current?.sessions?.[key]);
  return <section className="page detail-page"><button className="back-link" onClick={back}>← Back</button><div className="event-sheet page-sheet"><div className="event-hero"><div><SeriesTag series={series}/><small>ROUND {event?.round||latest?.round||'—'} · {event?.city||latest?.event?.city}</small><h1>{event?.name||latest?.event?.name||'Race event'}</h1><p><Flag country={event?.country||latest?.event?.country}/>{event?.country||latest?.event?.country} · {event?.rain??latest?.event?.rain}% rain baseline · {event?.temp??latest?.event?.temp}°C climate baseline</p></div><div className="event-dna"><b>{identity.car}</b><span>Favoured car profile</span><b>{identity.driver}</b><span>Favoured driver profile</span></div></div><div className="tab-row event-tabs">{['Overview','Current Year','History','Stats'].map((item)=><Pill key={item} active={tab===item} onClick={()=>setTab(item)}>{item}</Pill>)}</div>
  {tab==='Overview'&&<div className="event-overview"><Panel title="Most recent podium" eyebrow={latest?`${latest.year} ${series}`:'NO RESULT'}>{latest?<div className="podium-list">{latest.podium?.map((podium)=>{const driver=getDriver(universe,podium.driverId);const team=getTeam(universe,podium.teamId);return <button key={podium.driverId} onClick={()=>openDriver(driver?.id)}><strong>P{podium.position}</strong><Flag driver={driver}/><SeatBadge driver={driver} team={team}/><span><b>{driver?.name}</b><small>{team?.name}</small></span></button>})}<div className="overview-facts"><span><small>TEAM WINNER</small><button onClick={()=>openTeam(latest.teamWinnerId)}>{getTeam(universe,latest.teamWinnerId)?.name||'—'}</button></span><span><small>POLE</small><button onClick={()=>openDriver(latest.poleId)}>{getDriver(universe,latest.poleId)?.name||'—'}</button></span></div></div>:<Empty title="No completed edition" body="Complete this event to create its first podium and records."/>}</Panel><Panel title="Circuit profile" eyebrow="PERFORMANCE DNA"><div className="skill-grid">{Object.entries(event?.traits||latest?.event?.traits||{}).map(([key,value])=><Progress key={key} label={key} value={value}/>)}</div><p className="model-note">The circuit changes the competitive order. Car architecture, engine power, reliability, tyre life, driver specialty and weather are all weighted differently here.</p></Panel><Panel title="Historical winners" eyebrow="TOP THREE"><div className="event-leaders">{winLeaders.length?winLeaders.slice(0,3).map(([id,count],index)=><button key={id} onClick={()=>openDriver(id)}><strong>{index+1}</strong><Flag driver={getDriver(universe,id)}/><span><b>{getDriver(universe,id)?.name||'Historic driver'}</b><small>{count} wins</small></span></button>):<p>No historical winners yet.</p>}</div></Panel><Panel title="Pole specialists" eyebrow="TOP THREE"><div className="event-leaders">{poleLeaders.length?poleLeaders.slice(0,3).map(([id,count],index)=><button key={id} onClick={()=>openDriver(id)}><strong>{index+1}</strong><Flag driver={getDriver(universe,id)}/><span><b>{getDriver(universe,id)?.name||'Historic driver'}</b><small>{count} poles</small></span></button>):<p>No pole history yet.</p>}</div></Panel><Panel title="Fastest laps ever" eyebrow="TOP THREE"><div className="event-leaders">{fastest.length?fastest.map((record,index)=><button key={`${record.year}-${record.fastestLapDriverId}`} onClick={()=>openDriver(record.fastestLapDriverId)}><strong>{index+1}</strong><Flag driver={getDriver(universe,record.fastestLapDriverId)}/><span><b>{getDriver(universe,record.fastestLapDriverId)?.name||'Historic driver'}</b><small>{record.year} · {lapDisplay(record.fastestLapTime)}</small></span></button>):<p>No fastest laps yet.</p>}</div></Panel></div>}
  {tab==='Current Year'&&<>{current?<><div className="tab-row scroll session-tabs">{sessionKeys.map((key)=><Pill key={key} active={sessionKey===key} onClick={()=>setSessionKey(key)}>{current.sessions[key]?.label||key}</Pill>)}</div><Panel title={current.sessions[sessionKey]?.label||sessionKey} eyebrow={`${universe.year} · ${current.sessions[sessionKey]?.weather||'CONDITIONS'}${current.sessions[sessionKey]?.temperature!=null?` · ${current.sessions[sessionKey].temperature}°C`:''}${current.sessions[sessionKey]?.thermal&&current.sessions[sessionKey].thermal!=='Normal'?` · ${current.sessions[sessionKey].thermal}`:''}`}><EventResultTable universe={universe} session={current.sessions[sessionKey]} openDriver={openDriver}/></Panel></>:<Empty title={`No completed ${universe.year} edition`} body="After this race is finished, every Friday session, Q1, Q2, Q3 and the race will appear here with full times and points."/>}</>}
  {tab==='History'&&<Panel title="Edition by edition" eyebrow={`${series} HISTORY`}><div className="event-history-table"><div><b>Year</b><b>Winner / team</b><b>Second</b><b>Third</b><b>Fastest lap</b></div>{records.map((record)=>{const first=getDriver(universe,record.winnerId);const second=getDriver(universe,record.podium?.[1]?.driverId);const third=getDriver(universe,record.podium?.[2]?.driverId);const fast=getDriver(universe,record.fastestLapDriverId);return <div key={record.id}><strong>{record.year}</strong><span><b>{first?.name||'—'}</b><small>{getTeam(universe,record.teamWinnerId)?.name||'—'}</small></span><span>{second?.name||'—'}</span><span>{third?.name||'—'}</span><span>{fast?.name||'—'}<small>{lapDisplay(record.fastestLapTime)}</small></span></div>})}</div></Panel>}
  {tab==='Stats'&&<div className="event-overview"><Panel title="Drivers with most wins" eyebrow="ALL TIME"><div className="event-leaders">{winLeaders.map(([id,count],index)=><button key={id} onClick={()=>openDriver(id)}><strong>{index+1}</strong><Flag driver={getDriver(universe,id)}/><span><b>{getDriver(universe,id)?.name||'Historic driver'}</b><small>{count} victories</small></span></button>)}</div></Panel><Panel title="Drivers with most poles" eyebrow="ALL TIME"><div className="event-leaders">{poleLeaders.map(([id,count],index)=><button key={id} onClick={()=>openDriver(id)}><strong>{index+1}</strong><Flag driver={getDriver(universe,id)}/><span><b>{getDriver(universe,id)?.name||'Historic driver'}</b><small>{count} poles</small></span></button>)}</div></Panel><Panel title="Teams with most wins" eyebrow="ALL TIME"><div className="event-leaders">{teamLeaders.map(([id,count],index)=><button key={id} onClick={()=>openTeam(id)}><strong>{index+1}</strong><TeamStripe team={getTeam(universe,id)}/><span><b>{getTeam(universe,id)?.name||'Historic team'}</b><small>{count} wins</small></span></button>)}</div></Panel></div>}
  </div></section>
}

function DriverPage({universe,driver,back,openTeam,openStaff}){
  if(!driver)return <section className="page"><Empty title="Driver not found" body="This career no longer exists in the active universe."/></section>;const team=getTeam(universe,driver.teamId);const engineer=getStaff(universe,driver.engineerId);const history=[...(driver.career.seasons||[])].reverse();const transfers=[...(driver.transferHistory||[])].slice(0,12);
  return <section className="page detail-page"><button className="back-link" onClick={back}>← Back</button><div className="profile-hero" style={{'--team':team?.primary||team?.color||SERIES_META[driver.series]?.color||'#555'}}><div><SeriesTag series={driver.series} role={driver.role}/><RarityTag rarity={driver.rarity}/><SeatBadge driver={driver} team={team}/></div><Flag driver={driver}/><h1>{driver.name}</h1><p>{driver.country} · {driver.age} years · {driver.style} · {driver.trackSpecialty}</p>{team&&<button className="team-link" onClick={()=>openTeam(team.id)}><TeamStripe team={team}/>{team.name} · Driver {driver.seat}</button>}</div><div className="profile-stats"><span><b>{currentRating(driver)}</b>Current ability</span><span><b>{driver.baseTalent}</b>Base ceiling</span><span><b>{careerMultiplier(driver).toFixed(3)}</b>Career year</span><span><b>{driver.annualForm.toFixed(3)}</b>Annual form</span><span><b>{driver.career?.f1Starts||0}</b>F1 starts</span><span><b>{driver.career?.titles||0}</b>World titles</span><span><b>{driver.teamJoinedYear||universe.year}</b>Joined team</span><span><b>{driver.happiness?.overall||'—'}</b>Happiness</span></div><p className="model-note"><b>Current skills are the values used today.</b> Raw skills are multiplied by the career curve and annual form. A 99 base driver at 0.81 now displays around 80—not ten artificial 100s.</p><div className="two-col"><Panel title="Driver identity" eyebrow="ROLE + CONTRACT"><div className="details"><span><b>Team status</b>{driver.role==='Race driver'?`Driver ${driver.seat}`:driver.role}</span><span><b>Race engineer</b>{engineer?<button className="inline-link" onClick={()=>openStaff(engineer.id)}>{engineer.name} · {engineer.rarity}</button>:'—'}</span><span><b>Contract through</b>{driver.contract?.through||'—'}</span><span><b>Salary</b>{money(driver.contract?.salary||0)}</span><span><b>Salary demand</b>{money(driver.salaryDemand||0)}</span><span><b>Commercial</b>{driver.commercial}</span></div></Panel><Panel title="Happiness" eyebrow="TRANSFER PRESSURE"><div className="skill-grid"><Progress label="Overall" value={driver.happiness?.overall||60}/><Progress label="Role" value={driver.happiness?.role||60}/><Progress label="Results" value={driver.happiness?.results||60}/><Progress label="Salary" value={driver.happiness?.salary||60}/></div><div className="reason-tags">{(driver.happiness?.reasons||[]).map((reason)=><span key={reason}>{reason}</span>)}</div></Panel></div><h2>Current skills</h2><div className="skill-grid effective-skills">{Object.keys(driver.skills||{}).map((key)=><div key={key}><Progress label={key.replace(/([A-Z])/g,' $1')} value={effectiveDriverSkill(driver,key)}/><small>Raw {driver.skills[key]}</small></div>)}</div><h2>Career curve</h2><div className="career-curve">{driver.careerCurve.map((value,index)=><i key={index} className={index===driver.curveIndex?'active':''} style={{height:`${Math.max(8,(value-.74)*260)}%`}} title={`Age ${driver.debutAge+index}: ${value}`}/>)}</div><div className="two-col"><Panel title="Career record" eyebrow="ALL SERIES"><div className="details"><span><b>F1 starts</b>{driver.career.f1Starts}</span><span><b>F1 wins</b>{driver.career.f1Wins}</span><span><b>F1 podiums</b>{driver.career.f1Podiums}</span><span><b>F1 titles</b>{driver.career.titles}</span><span><b>Other titles</b>{driver.career.seriesTitles}</span><span><b>F1 poles</b>{driver.career.f1Poles}</span></div></Panel><Panel title="Season history" eyebrow="YEAR BY YEAR">{history.length?<div className="career-history">{history.map((season)=><div key={`${season.year}-${season.series}`}><b>{season.year}</b><SeriesTag series={season.series}/><span>P{season.position} · {season.points} pts · {season.wins} wins</span></div>)}</div>:<p>No completed seasons yet.</p>}</Panel></div><Panel title="Transfer history" eyebrow="MARKET">{transfers.length?<div className="transfer-history">{transfers.map((move)=><div key={move.id}><b>{move.year}</b><span>{move.from.teamName} ({move.from.seat||'—'}) {move.from.series}, {money(move.from.salary)}</span><strong>→</strong><span>{move.to.teamName} ({move.to.seat||'—'}) {move.to.series}, {money(move.to.salary)}</span></div>)}</div>:<p>No recorded moves yet.</p>}</Panel></section>;
}

function FacilityCard({label,value}){return <div className="facility-card"><span>{label}</span><b>{Number(value||0).toFixed(1)}</b><i><em style={{width:`${clamp((value||0)*10,0,100)}%`}}/></i><small>of 10</small></div>}
function TeamPage({universe,team,back,openDriver,openStaff}){
  if(!team)return <section className="page"><Empty title="Team not found" body="This organization is not available."/></section>;
  const isF1=universe.teams.some((item)=>item.id===team.id);
  const series=isF1?'F1':team.series;
  const brand=isF1?getMainBrand(universe,team.mainBrandId):null;
  const drivers=universe.drivers.filter((driver)=>driver.teamId===team.id&&driver.role==='Race driver'&&driver.active).sort((a,b)=>(a.seat||9)-(b.seat||9));
  const tests=isF1?(team.testDriverIds||[]).map((id)=>getDriver(universe,id)).filter(Boolean):[];
  const staff=(team.staffIds||[]).map((id)=>getStaff(universe,id)).filter(Boolean);
  const sponsors=(team.sponsorIds||[]).map((id)=>getSponsor(universe,id)).filter(Boolean);
  const carData=isF1?(team.car||{}):(team.carProfile||{});
  const carQuality=team.baseline||team.rating||avg(Object.values(carData));
  const finances=team.finances||{};
  const income=finances.totalIncome??finances.income??0;
  const expenses=finances.totalExpenses??finances.expenses??0;
  return <section className="page detail-page">
    <button className="back-link" onClick={back}>← Back</button>
    <div className="team-hero page-team-hero" style={{background:`linear-gradient(125deg,${team.primary||team.color||SERIES_META[series]?.color},#111 72%)`}}>
      <div><SeriesTag series={series}/><small>{brand?`${brand.tier.toUpperCase()} MAIN BRAND · ${brand.country.toUpperCase()}`:(team.country||seriesName(series)).toUpperCase()}</small><h1>{team.name}</h1><p>{brand?`${brand.name} identity · ${getEngine(universe,team.engineId)?.name} power · Heritage ${team.heritage}`:`${SERIES_META[series]?.name} entrant · permanent universe organization`}</p></div>
      {isF1?<LiveryCar team={team} universe={universe}/>:<div className="feeder-team-mark" style={{'--team':team.color||SERIES_META[series]?.color}}>{team.short||series}</div>}
    </div>
    <div className="profile-stats"><span><b>{Math.round(carQuality)}</b>Car</span><span><b>{isF1?(team.season?.points??0):(team.points??team.season?.points??0)}</b>Points</span><span><b>{money(finances.cash||0)}</b>Cash</span><span><b>{money(income)}</b>Income</span><span><b>{money(expenses)}</b>Expenses</span><span><b>{money(finances.projectedBalance||0)}</b>Balance</span></div>
    <div className="two-col"><Panel title="Race drivers" eyebrow="TEAM HIERARCHY"><div className="people-list">{drivers.map((driver)=><button key={driver.id} onClick={()=>openDriver(driver.id)}><Flag driver={driver}/><SeatBadge driver={driver} team={team}/><RarityTag rarity={driver.rarity}/><span><b>{driver.name}</b><small>Driver {driver.seat} · current {currentRating(driver)} · joined {driver.teamJoinedYear||universe.year}</small></span></button>)}</div></Panel>
      {isF1&&<Panel title="Test drivers" eyebrow="DEVELOPMENT + BACKUP"><div className="people-list">{tests.map((driver)=><button key={driver.id} onClick={()=>openDriver(driver.id)}><Flag driver={driver}/><SeatBadge driver={driver} team={team}/><RarityTag rarity={driver.rarity}/><span><b>{driver.name}</b><small>Feedback {effectiveDriverSkill(driver,'feedback')} · current {currentRating(driver)}</small></span></button>)}</div></Panel>}
    </div>
    <Panel title="Facilities" eyebrow="1–10 · DECAY + INVESTMENT"><p className="model-note">Facilities decay every off-season. Cash-rich teams reinvest in weak areas; aero, simulator, manufacturing, pit crew and academy quality feed directly into car development and operational performance.</p><div className="facility-grid">{Object.entries(team.facilities||{}).map(([key,value])=><FacilityCard key={key} label={key.replace(/([A-Z])/g,' $1')} value={value}/>)}</div></Panel>
    <Panel title="Leadership and engineering" eyebrow="RARITY + TRANSFER MARKET"><div className="staff-grid staff-clickable">{staff.length?staff.slice().sort((a,b)=>a.role.localeCompare(b.role)||b.rating-a.rating).map((member)=>{const assigned=member.assignedDriverId?getDriver(universe,member.assignedDriverId):null;return <button key={member.id} onClick={()=>openStaff(member.id)}><Flag country={member.country}/><RarityTag rarity={member.rarity}/><span><b>{member.name}</b><small>{member.role}{member.role==='Race Engineer'?` · Driver ${member.assignedSeat||'—'}${assigned?` (${assigned.name})`:''}`:` · ${member.specialty}`}</small></span><em>{member.rating}</em></button>}):<p>No staff records.</p>}</div></Panel>
    <div className="two-col"><Panel title="Financial structure" eyebrow="INCOME VS COSTS"><div className="finance-breakdown"><div className="income"><h4>Income</h4><span><b>{isF1?'Main brand':'Core funding'}</b>{money(finances.mainFunding??finances.income??0)}</span><span><b>{isF1?'Secondary sponsors':'Prize / commercial'}</b>{money(isF1?finances.secondarySponsorIncome:finances.prizeMoney)}</span>{isF1&&<span><b>Prize money</b>{money(finances.prizeMoney)}</span>}<span className="finance-total"><b>Total</b>{money(income)}</span></div><div className="cost"><h4>Costs</h4>{isF1&&<span><b>Drivers + tests</b>{money(finances.driverCost)}</span>}<span><b>Key staff</b>{money(finances.staffCost)}</span><span><b>Facilities</b>{money(finances.facilityInvestment||0)}</span>{isF1&&<span><b>Development</b>{money(finances.developmentCost)}</span>}<span className="finance-total"><b>Total</b>{money(expenses)}</span></div></div></Panel>
      {isF1?<Panel title="Secondary sponsors" eyebrow="COUNTRY ACCESS">{sponsors.length?<div className="sponsor-grid">{sponsors.map((sponsor)=><div key={sponsor.id} style={{'--sponsor':sponsor.colors[0]}}><b>{sponsor.name}</b><span><Flag country={sponsor.country}/>{sponsor.country}</span><small>{sponsor.industry} · base {money(sponsor.value)}</small></div>)}</div>:<p>No secondary sponsors.</p>}</Panel>:<Panel title="Organization model" eyebrow={series}><div className="details"><span><b>Competition</b>{seriesName(series)}</span><span><b>Team since</b>{team.lineage?.[0]?.year||2026}</span><span><b>Staff members</b>{staff.length}</span><span><b>Facility average</b>{avg(Object.values(team.facilities||{})).toFixed(1)} / 10</span></div></Panel>}
    </div>
    <Panel title="Car profile" eyebrow="CURRENT PACKAGE"><div className="skill-grid">{Object.entries(carData).map(([key,value])=><Progress key={key} label={key} value={value}/>)}</div></Panel>
  </section>;
}
function StaffPage({universe,member,back,openTeam,openDriver}){if(!member)return <section className="page"><Empty title="Staff member not found" body="This staff record is unavailable."/></section>;const team=getTeam(universe,member.teamId);const driver=getDriver(universe,member.assignedDriverId);return <section className="page detail-page"><button className="back-link" onClick={back}>← Back</button><div className="profile-hero staff-hero" style={{'--team':team?.primary||team?.color||'#555'}}><div><RarityTag rarity={member.rarity}/></div><Flag country={member.country}/><h1>{member.name}</h1><p>{member.role} · {member.specialty} · {member.age} years old</p>{team&&<button className="team-link" onClick={()=>openTeam(team.id)}><TeamStripe team={team}/>{team.name}</button>}</div><div className="profile-stats"><span><b>{member.rating}</b>Rating</span><span><b>{member.rarity}</b>Rarity</span><span><b>{member.contractThrough}</b>Contract</span><span><b>{money(member.salary)}</b>Salary</span><span><b>{member.titles||0}</b>Titles</span><span><b>{member.wins||0}</b>Wins</span></div><div className="two-col"><Panel title="Role skills" eyebrow="STAFF PROFILE"><div className="skill-grid"><Progress label="Commercial" value={member.commercial}/><Progress label="Technical" value={member.technical}/><Progress label="Sporting" value={member.sporting}/><Progress label="Strategy" value={member.strategy}/><Progress label="Ambition" value={member.ambition}/></div></Panel><Panel title="Current assignment" eyebrow="ORGANIZATION"><div className="details"><span><b>Team</b>{team?.name||'Free agent'}</span><span><b>Joined</b>{member.teamJoinedYear||'—'}</span><span><b>Personality</b>{member.personality}</span>{member.role==='Race Engineer'&&<span><b>Assigned driver</b>{driver?<button className="inline-link" onClick={()=>openDriver(driver.id)}>Driver {member.assignedSeat}: {driver.name}</button>:'Unassigned'}</span>}</div></Panel></div><Panel title="Career history" eyebrow="TRANSFERS">{member.history?.length?<div className="career-history">{member.history.slice().reverse().map((entry,index)=><div key={`${entry.year}-${index}`}><b>{entry.year}</b><span>{getTeam(universe,entry.teamId)?.name||entry.teamId} · {entry.role}</span></div>)}</div>:<p>No prior transfer recorded.</p>}</Panel></section>}

createRoot(document.getElementById('root')).render(<App/>);
